package com.ccb.testmanagement.report;

// 关键逻辑：所有读写以认证用户的租户、测试大类和项目为共同边界；写入由事务与审计保持一致性。

import com.ccb.common.api.PageQuery;
import com.ccb.common.api.PageResult;
import com.ccb.common.exception.BusinessException;
import com.ccb.common.exception.ErrorCode;
import com.ccb.security.model.AuthUser;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.*;
import java.util.concurrent.ThreadLocalRandom;

/** 测试报告：版本只追加事实快照，人工补充只作用于指定版本。 */
@Service
public class TestReportService {
    private static final Set<String> DOMAINS=Set.of("application-assembly","user-testing","non-functional","security");
    public static final List<String> CHAPTERS=List.of("OVERVIEW","SCOPE_STAT","EXECUTION_STAT","DEFECT_STAT","SCOPE_DETAIL","DEFECT_DETAIL");
    private final JdbcTemplate jdbc; private final ObjectMapper mapper;
    public TestReportService(JdbcTemplate jdbc,ObjectMapper mapper){this.jdbc=jdbc;this.mapper=mapper;}

    public Map<String,Object> tree(String domain,long projectId,AuthUser user){scope(domain,projectId,user); Map<String,Object> project=jdbc.queryForMap("SELECT id,project_name FROM pm_project WHERE id=? AND tenant_id=? AND deleted=0",projectId,user.tenantId()); List<Map<String,Object>> systems=jdbc.queryForList("SELECT s.physical_subsystem_id AS id,COALESCE(NULLIF(p.short_name,''),REPLACE(p.name,'物理子系统','')) AS name,p.code FROM tm_test_participating_system s JOIN arch_physical_subsystem p ON p.id=s.physical_subsystem_id AND p.tenant_id=s.tenant_id AND p.deleted=0 WHERE s.tenant_id=? AND s.test_domain=? AND s.project_id=? AND s.enabled=1 AND s.deleted=0 ORDER BY name,p.id",user.tenantId(),domain,projectId); List<Map<String,Object>> specials=jdbc.queryForList("SELECT id,node_name FROM tm_test_plan_special_node WHERE tenant_id=? AND test_domain=? AND project_id=? AND deleted=0 ORDER BY node_name,id",user.tenantId(),domain,projectId); return Map.of("project",project,"systems",systems,"specials",specials);}
    public Map<String,Object> options(String domain,long projectId,Long systemId,AuthUser user){scope(domain,projectId,user); if(systemId!=null)system(domain,projectId,systemId,user); List<Map<String,Object>> rounds=jdbc.queryForList("SELECT id,round_name,planned_start_date,planned_end_date,status FROM tm_test_round WHERE tenant_id=? AND test_domain=? AND project_id=? AND deleted=0 ORDER BY sort_no,id",user.tenantId(),domain,projectId); List<Map<String,Object>> cycles=jdbc.queryForList("SELECT c.id,c.round_id,c.cycle_name,c.planned_start_date,c.planned_end_date,c.status FROM tm_test_cycle c JOIN tm_test_round r ON r.id=c.round_id AND r.tenant_id=c.tenant_id AND r.deleted=0 WHERE c.tenant_id=? AND r.test_domain=? AND r.project_id=? AND c.deleted=0 ORDER BY c.sort_no,c.id",user.tenantId(),domain,projectId); return Map.of("rounds",rounds,"cycles",cycles,"sections",CHAPTERS);}
    public PageResult<Map<String,Object>> list(String domain,long projectId,Long systemId,Long specialNodeId,String scopeType,String keyword,PageQuery page,AuthUser user){scope(domain,projectId,user); String scope=normalizeScope(scopeType,systemId,specialNodeId); validateScope(domain,projectId,scope,systemId,specialNodeId,user); String where=" WHERE r.tenant_id=? AND r.test_domain=? AND r.project_id=? AND r.scope_type=?"+("SYSTEM".equals(scope)?" AND r.physical_subsystem_id=?":"SPECIAL".equals(scope)?" AND r.special_node_id=?":"")+(keyword==null||keyword.isBlank()?"":" AND r.report_name LIKE ?"); List<Object> args=new ArrayList<>(List.of(user.tenantId(),domain,projectId,scope)); if("SYSTEM".equals(scope))args.add(systemId);if("SPECIAL".equals(scope))args.add(specialNodeId);if(keyword!=null&&!keyword.isBlank())args.add("%"+keyword.trim()+"%"); Long total=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_report r"+where,Long.class,args.toArray()); List<Object> rows=new ArrayList<>(args);rows.add((page.page()-1)*page.size());rows.add(page.size()); String sql="SELECT r.id,r.report_name,r.report_type,r.scope_type,r.round_id,r.cycle_id,r.physical_subsystem_id,r.special_node_id,r.current_version_no,CONCAT('V',r.current_version_no) AS current_version,r.generated_at,u.display_name AS generator_name,rr.round_name,c.cycle_name,COALESCE(NULLIF(s.short_name,''),REPLACE(s.name,'物理子系统','')) AS physical_system_name,n.node_name AS special_name FROM tm_test_report r LEFT JOIN sys_user u ON u.id=r.generated_by AND u.tenant_id=r.tenant_id LEFT JOIN tm_test_round rr ON rr.id=r.round_id LEFT JOIN tm_test_cycle c ON c.id=r.cycle_id LEFT JOIN arch_physical_subsystem s ON s.id=r.physical_subsystem_id LEFT JOIN tm_test_plan_special_node n ON n.id=r.special_node_id AND n.tenant_id=r.tenant_id"+where+" ORDER BY r.generated_at DESC,r.id DESC LIMIT ?,?"; return new PageResult<>(jdbc.queryForList(sql,rows.toArray()),total==null?0:total,page.page(),page.size());}
    @Transactional public Map<String,Object> generate(String domain,long projectId,Long systemId,Long specialNodeId,String scopeType,Long reportId,Map<String,Object> body,AuthUser user){scope(domain,projectId,user);String scope=normalizeScope(scopeType,systemId,specialNodeId);validateScope(domain,projectId,scope,systemId,specialNodeId,user);String name=required(body.get("report_name"),"报告名称",100);String type=required(body.get("report_type"),"报告类型",16).toUpperCase(Locale.ROOT);if(!Set.of("PROJECT","ROUND","CYCLE").contains(type))throw bad("报告类型无效");Long round=longOrNull(body.get("round_id"));Long cycle=longOrNull(body.get("cycle_id"));if("PROJECT".equals(type)){round=null;cycle=null;}if("ROUND".equals(type)&&round==null)throw bad("请选择关联轮次");if("CYCLE".equals(type)&&(round==null||cycle==null))throw bad("请选择关联轮次和周期");validateRound(domain,projectId,"SYSTEM".equals(scope)?systemId:null,round,cycle,user);String source=String.valueOf(body.getOrDefault("source_type","LIVE")).toUpperCase(Locale.ROOT);if(!Set.of("LIVE","SNAPSHOT").contains(source))throw bad("数据来源无效");if("SNAPSHOT".equals(source)&&round==null)throw bad("项目报告仅支持当前实时数据");List<String> sections=sections(body.get("sections"));long saved=reportId==null?next():reportId; if(reportId==null){Long same=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_report WHERE tenant_id=? AND test_domain=? AND project_id=? AND scope_type=? AND ((physical_subsystem_id IS NULL AND ? IS NULL) OR physical_subsystem_id=?) AND ((special_node_id IS NULL AND ? IS NULL) OR special_node_id=?) AND report_name=?",Long.class,user.tenantId(),domain,projectId,scope,systemId,systemId,specialNodeId,specialNodeId,name);if(same!=null&&same>0)throw conflict("当前节点已有同名报告");jdbc.update("INSERT INTO tm_test_report(id,tenant_id,test_domain,project_id,physical_subsystem_id,scope_type,special_node_id,report_name,report_type,round_id,cycle_id,source_type,selected_sections,current_version_no,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,0,?,?)",saved,user.tenantId(),domain,projectId,"SYSTEM".equals(scope)?systemId:null,scope,"SPECIAL".equals(scope)?specialNodeId:null,name,type,round,cycle,source,json(sections),user.id(),user.id());}else{Map<String,Object> existing=requireReport(reportId,domain,projectId,user.tenantId());if(!sameScope(existing,scope,systemId,specialNodeId))throw bad("报告不属于当前树节点");jdbc.update("UPDATE tm_test_report SET report_name=?,report_type=?,round_id=?,cycle_id=?,source_type=?,selected_sections=?,updated_by=? WHERE id=? AND tenant_id=?",name,type,round,cycle,source,json(sections),user.id(),saved,user.tenantId());}
        int version=nextVersion(saved,user.tenantId());long versionId=next();Map<String,Object> snapshot=snapshotForSource(domain,projectId,"SYSTEM".equals(scope)?systemId:null,round,cycle,sections,source,user);jdbc.update("INSERT INTO tm_test_report_version(id,tenant_id,report_id,version_no,snapshot_json,generated_by) VALUES(?,?,?,?,?,?)",versionId,user.tenantId(),saved,version,json(snapshot),user.id());jdbc.update("UPDATE tm_test_report SET current_version_no=?,generated_by=?,generated_at=CURRENT_TIMESTAMP,updated_by=? WHERE id=? AND tenant_id=?",version,user.id(),user.id(),saved,user.tenantId());audit(domain,projectId,saved,versionId,reportId==null?"GENERATE":"REGENERATE",user);return detail(domain,projectId,saved,versionId,user);}
    public Map<String,Object> detail(String domain,long projectId,long reportId,Long versionId,AuthUser user){Map<String,Object> report=requireReport(reportId,domain,projectId,user.tenantId()); List<Map<String,Object>> versions=jdbc.queryForList("SELECT id,version_no,generated_by,generated_at FROM tm_test_report_version WHERE tenant_id=? AND report_id=? ORDER BY version_no DESC",user.tenantId(),reportId);if(versions.isEmpty())return Map.of("report",report,"versions",List.of()); long current=versionId==null?number(versions.get(0).get("id")):versionId;Map<String,Object> version=requireVersion(current,reportId,user.tenantId());Map<String,Object> facts=jsonMap(version.get("snapshot_json"));List<Map<String,Object>> supplements=jdbc.queryForList("SELECT chapter_code,content_html,updated_at,(SELECT display_name FROM sys_user u WHERE u.id=s.updated_by AND u.tenant_id=s.tenant_id AND u.deleted=0) AS updater_name FROM tm_test_report_supplement s WHERE s.tenant_id=? AND s.report_version_id=? ORDER BY chapter_code",user.tenantId(),current);return Map.of("report",report,"versions",versions,"version",version,"snapshot",facts,"supplements",supplements);}
    public List<Map<String,Object>> history(String domain,long projectId,long reportId,AuthUser user){requireReport(reportId,domain,projectId,user.tenantId());return jdbc.queryForList("SELECT id,version_no,generated_at,(SELECT display_name FROM sys_user u WHERE u.id=v.generated_by AND u.tenant_id=v.tenant_id AND u.deleted=0) AS generator_name FROM tm_test_report_version v WHERE tenant_id=? AND report_id=? ORDER BY version_no DESC",user.tenantId(),reportId);}
    @Transactional public void supplement(String domain,long projectId,long reportId,long versionId,Map<String,Object> body,AuthUser user){requireReport(reportId,domain,projectId,user.tenantId());requireVersion(versionId,reportId,user.tenantId());String chapter=required(body.get("chapter_code"),"章节",32).toUpperCase(Locale.ROOT);if(!CHAPTERS.contains(chapter))throw bad("章节无效");String html=String.valueOf(body.getOrDefault("content_html","")).trim();Long exists=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_report_supplement WHERE tenant_id=? AND report_version_id=? AND chapter_code=?",Long.class,user.tenantId(),versionId,chapter);if(exists!=null&&exists>0)jdbc.update("UPDATE tm_test_report_supplement SET content_html=?,updated_by=? WHERE tenant_id=? AND report_version_id=? AND chapter_code=?",html,user.id(),user.tenantId(),versionId,chapter);else jdbc.update("INSERT INTO tm_test_report_supplement(id,tenant_id,report_version_id,chapter_code,content_html,updated_by) VALUES(?,?,?,?,?,?)",next(),user.tenantId(),versionId,chapter,html,user.id());audit(domain,projectId,reportId,versionId,"SUPPLEMENT",user);}
    @Transactional public void delete(String domain,long projectId,long id,AuthUser user){Map<String,Object> report=requireReport(id,domain,projectId,user.tenantId());jdbc.update("INSERT INTO tm_test_configuration_audit(id,tenant_id,test_domain,project_id,entity_type,entity_id,action_code,operator_id,detail_json) VALUES(?,?,?,?,?,?,?,?,?)",next(),user.tenantId(),domain,projectId,"REPORT",id,"DELETE",user.id(),json(Map.of("report_name",String.valueOf(report.get("report_name")),"version_count",nextVersion(id,user.tenantId())-1)));audit(domain,projectId,id,null,"DELETE",user);jdbc.update("DELETE FROM tm_test_report WHERE id=? AND tenant_id=?",id,user.tenantId());}
    @Transactional public void recordDownload(String domain,long projectId,long id,Long versionId,String format,AuthUser user){requireReport(id,domain,projectId,user.tenantId());if(versionId!=null)requireVersion(versionId,id,user.tenantId());audit(domain,projectId,id,versionId,"DOWNLOAD_"+format.toUpperCase(Locale.ROOT),user);}
    public Map<String,Object> snapshot(String d,long p,Long sys,Long round,Long cycle,List<String> sections,AuthUser u){String filter=" tenant_id=? AND test_domain=? AND project_id=? AND deleted=0"+(sys==null?"":" AND physical_subsystem_id=?");Object[] args=sys==null?new Object[]{u.tenantId(),d,p}:new Object[]{u.tenantId(),d,p,sys};long scopes=count("tm_test_scope",filter,args);long cases=count("tm_test_case",filter,args);String efilter=filter+(round==null?"":" AND round_id=?")+(cycle==null?"":" AND cycle_id=?");List<Object> eargs=new ArrayList<>(Arrays.asList(args));if(round!=null)eargs.add(round);if(cycle!=null)eargs.add(cycle);long executions=count("tm_test_execution",efilter,eargs.toArray());long success=count("tm_test_execution",efilter+" AND execution_status='SUCCESS'",eargs.toArray());long failed=count("tm_test_execution",efilter+" AND execution_status='FAILED'",eargs.toArray());long blocked=count("tm_test_execution",efilter+" AND execution_status='BLOCKED'",eargs.toArray());long defects=count("tm_test_defect",filter,args);long open=count("tm_test_defect",filter+" AND status NOT IN ('RESOLVED','CLOSED')",args);Map<String,Object> facts=new LinkedHashMap<>();facts.put("snapshot_at",LocalDateTime.now().toString());facts.put("sections",sections);facts.put("scope_total",scopes);facts.put("case_total",cases);facts.put("execution_total",executions);facts.put("execution_success",success);facts.put("execution_failed",failed);facts.put("execution_blocked",blocked);facts.put("execution_rate",rate(success+failed+blocked,executions));facts.put("success_rate",rate(success,executions));facts.put("defect_total",defects);facts.put("defect_open",open);facts.put("scope_details",jdbc.queryForList("SELECT scope_code,scope_name FROM tm_test_scope WHERE"+filter+" ORDER BY scope_code LIMIT 200",args));facts.put("defect_details",jdbc.queryForList("SELECT defect_code,summary,status,severity FROM tm_test_defect WHERE"+filter+" ORDER BY proposed_at DESC LIMIT 200",args));return facts;}
    private Map<String,Object> snapshotForSource(String d,long p,Long sys,Long round,Long cycle,List<String> sections,String source,AuthUser u){if("LIVE".equals(source))return snapshot(d,p,sys,round,cycle,sections,u);if(sys!=null)throw bad("系统级报告暂不支持项目轮次统计快照，请选择当前实时数据");List<Map<String,Object>> rows=jdbc.queryForList("SELECT snapshot_json,archived_at FROM tm_test_analytics_snapshot WHERE tenant_id=? AND test_domain=? AND project_id=? AND round_id=? AND report_key='EXECUTION_PROGRESS'",u.tenantId(),d,p,round);if(rows.isEmpty())throw bad("所选轮次尚未归档统计快照，请先在分析统计归档");Map<String,Object> archived=jsonMap(rows.get(0).get("snapshot_json"));Map<String,Object> facts=archived.get("summary") instanceof Map<?,?> raw?new LinkedHashMap<>(raw.entrySet().stream().collect(java.util.stream.Collectors.toMap(e->String.valueOf(e.getKey()),Map.Entry::getValue))):new LinkedHashMap<>(archived);facts.put("snapshot_at",String.valueOf(rows.get(0).get("archived_at")));facts.put("sections",sections);facts.put("source_type","SNAPSHOT");return facts;}
    private long count(String table,String filter,Object[] args){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE"+filter,Long.class,args);return n==null?0:n;} private double rate(long part,long total){return total==0?0:Math.round(part*10000D/total)/100D;}
    private String normalizeScope(String raw,Long systemId,Long specialNodeId){String scope=raw==null||raw.isBlank()?(systemId!=null?"SYSTEM":specialNodeId!=null?"SPECIAL":"PROJECT"):raw.toUpperCase(Locale.ROOT);if(!Set.of("PROJECT","SYSTEM","SPECIAL").contains(scope))throw bad("报告范围无效");if("PROJECT".equals(scope)&&(systemId!=null||specialNodeId!=null))throw bad("项目级报告不能绑定系统或专项");if("SYSTEM".equals(scope)&&(systemId==null||specialNodeId!=null))throw bad("请选择报告所属系统");if("SPECIAL".equals(scope)&&(specialNodeId==null||systemId!=null))throw bad("请选择报告所属专项");return scope;}
    private void validateScope(String d,long p,String scope,Long systemId,Long specialNodeId,AuthUser u){if("SYSTEM".equals(scope))system(d,p,systemId,u);if("SPECIAL".equals(scope)){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_plan_special_node WHERE id=? AND tenant_id=? AND test_domain=? AND project_id=? AND deleted=0",Long.class,specialNodeId,u.tenantId(),d,p);if(n==null||n==0)throw bad("专项节点不属于当前项目");}}
    private boolean sameScope(Map<String,Object> report,String scope,Long systemId,Long specialNodeId){if(!scope.equals(String.valueOf(report.get("scope_type"))))return false;if("SYSTEM".equals(scope))return Objects.equals(number(report.get("physical_subsystem_id")),systemId);if("SPECIAL".equals(scope))return Objects.equals(number(report.get("special_node_id")),specialNodeId);return true;}
    private void validateRound(String d,long p,Long s,Long r,Long c,AuthUser u){if(r!=null){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_round WHERE id=? AND tenant_id=? AND test_domain=? AND project_id=? AND deleted=0",Long.class,r,u.tenantId(),d,p);if(n==null||n==0)throw bad("轮次不属于当前项目");}if(c!=null){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_cycle WHERE id=? AND round_id=? AND tenant_id=? AND deleted=0",Long.class,c,r,u.tenantId());if(n==null||n==0)throw bad("周期不属于所选轮次");}}
    private Map<String,Object> requireReport(long id,String d,long p,long tenant){List<Map<String,Object>> rows=jdbc.queryForList("SELECT r.*,COALESCE(NULLIF(s.short_name,''),REPLACE(s.name,'物理子系统','')) AS physical_system_name FROM tm_test_report r LEFT JOIN arch_physical_subsystem s ON s.id=r.physical_subsystem_id WHERE r.id=? AND r.tenant_id=? AND r.test_domain=? AND r.project_id=?",id,tenant,d,p);if(rows.isEmpty())throw bad("报告不存在或不属于当前项目");return rows.get(0);}private Map<String,Object> requireVersion(long id,long report,long tenant){List<Map<String,Object>> rows=jdbc.queryForList("SELECT id,version_no,snapshot_json,generated_by,generated_at FROM tm_test_report_version WHERE id=? AND report_id=? AND tenant_id=?",id,report,tenant);if(rows.isEmpty())throw bad("报告版本不存在");return rows.get(0);}private int nextVersion(long id,long tenant){Integer n=jdbc.queryForObject("SELECT COALESCE(MAX(version_no),0)+1 FROM tm_test_report_version WHERE tenant_id=? AND report_id=?",Integer.class,tenant,id);return n==null?1:n;}private void system(String d,long p,long s,AuthUser u){Long n=jdbc.queryForObject("SELECT COUNT(*) FROM tm_test_participating_system WHERE tenant_id=? AND test_domain=? AND project_id=? AND physical_subsystem_id=? AND enabled=1 AND deleted=0",Long.class,u.tenantId(),d,p,s);if(n==null||n==0)throw bad("请选择已参测系统");}private void scope(String d,long p,AuthUser u){if(!DOMAINS.contains(d))throw bad("测试大类无效");Long n=jdbc.queryForObject("SELECT COUNT(*) FROM pm_project WHERE id=? AND tenant_id=? AND deleted=0",Long.class,p,u.tenantId());if(n==null||n==0)throw bad("项目不存在或无权访问");}private List<String> sections(Object raw){if(!(raw instanceof Collection<?> list))return CHAPTERS;List<String> out=list.stream().map(String::valueOf).map(x->x.toUpperCase(Locale.ROOT)).filter(CHAPTERS::contains).distinct().toList();return out.isEmpty()?CHAPTERS:out;}private String json(Object value){try{return mapper.writeValueAsString(value);}catch(Exception e){throw bad("快照序列化失败");}}private Map<String,Object> jsonMap(Object value){try{return mapper.readValue(String.valueOf(value),new TypeReference<>(){});}catch(Exception e){return Map.of();}}private void audit(String d,long p,long r,Long v,String a,AuthUser u){jdbc.update("INSERT INTO tm_test_report_trace(id,tenant_id,test_domain,project_id,report_id,version_id,action_code,operator_id,detail_json) VALUES(?,?,?,?,?,?,?,?,?)",next(),u.tenantId(),d,p,r,v,a,u.id(),"{}");}private static long next(){return System.currentTimeMillis()*1000+ThreadLocalRandom.current().nextInt(1000);}private static long number(Object v){return ((Number)v).longValue();}private static Long longOrNull(Object v){try{if(v==null||String.valueOf(v).isBlank()||"null".equals(String.valueOf(v)))return null;return Long.parseLong(String.valueOf(v));}catch(Exception e){throw bad("编号无效");}}private static String required(Object v,String n,int max){String s=v==null?"":String.valueOf(v).trim();if(s.isBlank()||s.length()>max)throw bad(n+"无效");return s;}private static BusinessException bad(String s){return new BusinessException(ErrorCode.BAD_REQUEST,s);}private static BusinessException conflict(String s){return new BusinessException(ErrorCode.CONFLICT,s);}
}
